WITH b AS (SELECT arm,tool_name,CASE WHEN tool_name LIKE '%tilth_read' THEN json_array_length(input,'$.paths') WHEN tool_name LIKE '%tilth_search' THEN json_array_length(input,'$.queries') WHEN tool_name LIKE '%tilth_write' OR tool_name LIKE '%__Edit' THEN json_array_length(input,'$.edits') WHEN tool_name LIKE '%__Search' THEN json_array_length(input,'$.file_glob_patterns') END n FROM calls WHERE tool_name LIKE 'mcp__%') SELECT arm,tool_name,count(*) calls,count(*) FILTER(WHERE n>1) multi_item,sum(n) items,max(n) max_items FROM b GROUP BY arm,tool_name ORDER BY arm,tool_name;
SELECT arm,tool_name,count(*) FILTER(WHERE files>1) multi_file_calls,sum(files) file_targets,max(files) max_files FROM (SELECT arm,tool_name,tool_use_id,count(DISTINCT coalesce(json_extract_string(e.value,'$.path'),json_extract_string(e.value,'$.file_path'))) files FROM calls,json_each(json_extract(input,'$.edits')) e WHERE tool_name LIKE '%tilth_write' OR tool_name LIKE '%__Edit' GROUP BY arm,tool_name,tool_use_id) GROUP BY arm,tool_name;
